  function loadLocalState() {
    state.sales = readJson(STORAGE_KEYS.sales, []);
    state.quotes = readJson(STORAGE_KEYS.quotes, []);
    const savedProducts = readJson(STORAGE_KEYS.products, null);
    const sourceProducts = Array.isArray(savedProducts) && savedProducts.length ? savedProducts : sampleProducts;
    state.products = sourceProducts.map(normalizeProduct);
    saveLocalProducts();
  }

  async function initFirebase() {
    const config = window.SD_FIREBASE_CONFIG;
    const hasConfig = config && typeof config === 'object' && config.apiKey && config.projectId;
    state.firebase.collectionName = window.SD_FIRESTORE_COLLECTION || 'productos';
    state.firebase.collectionNames = uniqueList([
      ...(Array.isArray(window.SD_FIRESTORE_COLLECTIONS) ? window.SD_FIRESTORE_COLLECTIONS : []),
      window.SD_FIRESTORE_COLLECTION,
      'productos', 'products', 'inventario', 'catalogo', 'catalogoProductos', 'productos_catalogo', 'items'
    ]);
    state.firebase.realtimePaths = uniqueList([
      ...(Array.isArray(window.SD_REALTIME_PRODUCTS_PATHS) ? window.SD_REALTIME_PRODUCTS_PATHS : []),
      window.SD_REALTIME_PRODUCTS_PATH,
      'productos', 'products', 'inventario', 'catalogo', 'catalogoProductos', 'items'
    ]);

    if (!hasConfig) {
      setCloudStatus('Local', 'muted', 'Trabajando con almacenamiento local.');
      return;
    }

    try {
      setCloudStatus('Conectando', 'sync', 'Conectando con Firebase...');
      const finalConfig = { ...config };
      if (!finalConfig.databaseURL && window.SD_REALTIME_DATABASE_URL) {
        finalConfig.databaseURL = window.SD_REALTIME_DATABASE_URL;
      }

      const appModule = await import('https://www.gstatic.com/firebasejs/10.12.5/firebase-app.js');
      const firestoreModule = await import('https://www.gstatic.com/firebasejs/10.12.5/firebase-firestore.js');
      const storageModule = await import('https://www.gstatic.com/firebasejs/10.12.5/firebase-storage.js');
      const databaseModule = await import('https://www.gstatic.com/firebasejs/10.12.5/firebase-database.js').catch(() => null);
      const app = appModule.initializeApp(finalConfig);
      const db = firestoreModule.getFirestore(app);
      const storage = storageModule.getStorage(app);
      const rtdb = databaseModule ? databaseModule.getDatabase(app) : null;
      state.firebase = {
        enabled: true,
        ready: true,
        db,
        rtdb,
        storage,
        collectionName: state.firebase.collectionName,
        collectionNames: state.firebase.collectionNames,
        realtimePaths: state.firebase.realtimePaths,
        sourceType: 'firestore',
        sourcePath: state.firebase.collectionName,
        lastError: '',
        api: firestoreModule,
        databaseApi: databaseModule,
        storageApi: storageModule,
        unsubscribe: null
      };
      setCloudStatus('Firebase', 'online', 'Firebase conectado. Buscando catálogo...');
    } catch (error) {
      console.error(error);
      state.firebase.ready = false;
      setCloudStatus('Error nube', 'error', 'No se pudo conectar con Firebase.');
      showToast('No se pudo conectar Firebase. Se usará modo local.');
    }
  }

  async function loadProducts() {
    if (!state.firebase.ready) return;

    try {
      setCloudStatus('Cargando', 'sync', 'Buscando productos en Firebase...');
      const result = await readProductsFromFirebase();

      if (result.products.length) {
        state.products = result.products;
        state.firebase.sourceType = result.type;
        state.firebase.sourcePath = result.path;
        if (result.type === 'firestore') state.firebase.collectionName = result.path;
        saveLocalProducts();
        const sourceLabel = result.type === 'realtime' ? `Realtime DB: ${result.path}` : `Firestore: ${result.path}`;
        setCloudStatus('Firebase', 'online', `Productos cargados desde ${sourceLabel}. Cambios en vivo activados.`);
        startProductsListener();
        showToast(`Catálogo cargado desde Firebase (${result.products.length}).`);
      } else {
        const tried = result.tried.join(', ');
        state.firebase.lastError = result.errors.join(' | ');
        console.warn('SD COMAYAGUA: no se encontraron productos en Firebase.', { tried, errors: result.errors });
        setCloudStatus('Firebase vacío', 'warning', `No se encontraron productos. Revisado: ${tried}`);
        showToast('No encontré catálogo en Firebase. Revisa colección/path o reglas.');
      }
    } catch (error) {
      console.error('SD COMAYAGUA: error al leer Firebase', error);
      state.firebase.lastError = error.message || String(error);
      setCloudStatus('Error nube', 'error', 'Error al leer productos de Firebase. Mira la consola del navegador.');
      showToast('Firebase conectó, pero no dejó leer el catálogo.');
    }
  }

  async function readProductsFromFirebase() {
    const errors = [];
    const tried = [];

    for (const collectionName of state.firebase.collectionNames) {
      if (!collectionName) continue;
      tried.push(`Firestore/${collectionName}`);
      try {
        const products = await readFirestoreCollection(collectionName);
        if (products.length) return { type: 'firestore', path: collectionName, products, tried, errors };
      } catch (error) {
        errors.push(`Firestore/${collectionName}: ${error.code || error.message || error}`);
      }
    }

    if (state.firebase.rtdb && state.firebase.databaseApi) {
      for (const path of state.firebase.realtimePaths) {
        if (!path) continue;
        tried.push(`Realtime/${path}`);
        try {
          const products = await readRealtimePath(path);
          if (products.length) return { type: 'realtime', path, products, tried, errors };
        } catch (error) {
          errors.push(`Realtime/${path}: ${error.code || error.message || error}`);
        }
      }
    }

    return { type: 'none', path: '', products: [], tried, errors };
  }

  async function readFirestoreCollection(collectionName) {
    const { collection, getDocs, query, limit } = state.firebase.api;
    const ref = collection(state.firebase.db, collectionName);
    const snapshot = await getDocs(query(ref, limit(800)));
    return snapshot.docs.map((doc) => normalizeProduct({ ...doc.data(), id: doc.id })).filter((product) => product.name);
  }

  async function readRealtimePath(path) {
    const { ref, get } = state.firebase.databaseApi;
    const snapshot = await get(ref(state.firebase.rtdb, path));
    if (!snapshot.exists()) return [];
    return mapRealtimeProducts(snapshot.val()).map(normalizeProduct).filter((product) => product.name);
  }

  function startProductsListener() {
    if (!state.firebase.ready || !state.firebase.sourcePath || state.firebase.sourceType === 'none') return;
    stopProductsListener();
    try {
      if (state.firebase.sourceType === 'realtime' && state.firebase.rtdb && state.firebase.databaseApi) {
        const { ref, onValue } = state.firebase.databaseApi;
        const productsRef = ref(state.firebase.rtdb, state.firebase.sourcePath);
        state.firebase.unsubscribe = onValue(productsRef, (snapshot) => {
          const products = snapshot.exists()
            ? mapRealtimeProducts(snapshot.val()).map(normalizeProduct).filter((product) => product.name)
            : [];
          applyRemoteProducts(products, `Realtime DB: ${state.firebase.sourcePath}`);
        }, (error) => {
          console.error('SD COMAYAGUA: listener Realtime falló', error);
          setCloudStatus('Error nube', 'error', 'No se pudo escuchar cambios de Realtime Database.');
        });
        return;
      }

      const { collection, query, limit, onSnapshot } = state.firebase.api;
      const ref = collection(state.firebase.db, state.firebase.sourcePath || state.firebase.collectionName || 'productos');
      state.firebase.unsubscribe = onSnapshot(query(ref, limit(800)), (snapshot) => {
        const products = snapshot.docs.map((doc) => normalizeProduct({ ...doc.data(), id: doc.id })).filter((product) => product.name);
        applyRemoteProducts(products, `Firestore: ${state.firebase.sourcePath}`);
      }, (error) => {
        console.error('SD COMAYAGUA: listener Firestore falló', error);
        setCloudStatus('Error nube', 'error', 'No se pudo escuchar cambios de Firestore.');
      });
    } catch (error) {
      console.error('SD COMAYAGUA: no se pudo activar escucha en vivo', error);
      setCloudStatus('Firebase', 'warning', 'Firebase cargó, pero no se pudo activar actualización en vivo.');
    }
  }

  function stopProductsListener() {
    if (typeof state.firebase.unsubscribe === 'function') {
      try { state.firebase.unsubscribe(); } catch (error) { console.warn(error); }
    }
    state.firebase.unsubscribe = null;
  }

  function applyRemoteProducts(products, label) {
    state.products = products.map(normalizeProduct);
    saveLocalProducts();
    renderAll();
    setCloudStatus('Firebase', 'online', `${label}. Actualización automática activa.`);
  }

  function mapRealtimeProducts(value) {
    if (!value) return [];
    if (Array.isArray(value)) {
      return value
        .map((item, index) => item && typeof item === 'object' ? { ...item, id: item.id || String(index) } : null)
        .filter(Boolean);
    }
    if (typeof value !== 'object') return [];

    const nestedKeys = ['productos', 'products', 'items', 'catalogo', 'inventario'];
    for (const key of nestedKeys) {
      if (value[key] && typeof value[key] === 'object') {
        const nested = mapRealtimeProducts(value[key]);
        if (nested.length) return nested;
      }
    }

    return Object.entries(value)
      .map(([id, item]) => item && typeof item === 'object' ? { ...item, id: item.id || id } : null)
      .filter(Boolean);
  }

  async function syncNow() {
    saveLocalProducts();
    if (!state.firebase.ready) {
      showToast('Modo local activo. Agrega Firebase para sincronizar con la nube.');
      return;
    }
    stopProductsListener();
    await loadProducts();
    renderAll();
    showToast('Catálogo recargado desde Firebase.');
  }

  async function pushAllProductsToFirebase() {
    if (!state.firebase.ready) return;
    const writes = state.products.map((product) => saveProductToFirebase(product));
    await Promise.all(writes);
  }

  async function saveProductToFirebase(product) {
    if (!state.firebase.ready) return;
    if (state.firebase.sourceType === 'realtime' && state.firebase.rtdb && state.firebase.databaseApi) {
      const { ref, set } = state.firebase.databaseApi;
      await set(ref(state.firebase.rtdb, `${state.firebase.sourcePath}/${product.id}`), sanitizeForStorage(product));
      return;
    }
    const { collection, doc, setDoc } = state.firebase.api;
    const collectionPath = state.firebase.sourcePath || state.firebase.collectionName || 'productos';
    const ref = collection(state.firebase.db, collectionPath);
    await setDoc(doc(ref, product.id), sanitizeForStorage(product), { merge: true });
  }

  async function deleteProductFromFirebase(productId) {
    if (!state.firebase.ready) return;
    if (state.firebase.sourceType === 'realtime' && state.firebase.rtdb && state.firebase.databaseApi) {
      const { ref, remove } = state.firebase.databaseApi;
      await remove(ref(state.firebase.rtdb, `${state.firebase.sourcePath}/${productId}`));
      return;
    }
    const { collection, doc, deleteDoc } = state.firebase.api;
    const collectionPath = state.firebase.sourcePath || state.firebase.collectionName || 'productos';
    const ref = collection(state.firebase.db, collectionPath);
    await deleteDoc(doc(ref, productId));
  }

  function printAdminCatalog() {
    document.body.dataset.printMode = '';
    window.print();
  }

  function printComayaguaCatalog() {
    if (!el.localPrintDialog) return;
    el.localPrintShipping.value = '';
    openDialog('localPrintDialog');
    setTimeout(() => el.localPrintShipping.focus(), 120);
  }

  async function onLocalPrintSubmit(event) {
    event.preventDefault();
    const localShipping = Math.max(0, Math.ceil(Number(el.localPrintShipping.value || 0)));
    if (!Number.isFinite(localShipping)) {
      showToast('Escribe un precio de envío válido.');
      return;
    }
    closeDialog('localPrintDialog');
    preparePrintCatalog('comayagua', { localShipping });
    await waitForPrintAssets();
    window.print();
  }

  async function printHondurasCatalog() {
    preparePrintCatalog('honduras');
    await waitForPrintAssets();
    window.print();
  }

  function clearPrintCatalog() {
    document.body.dataset.printMode = '';
    if (el.printCatalog) {
      el.printCatalog.innerHTML = '';
      el.printCatalog.setAttribute('aria-hidden', 'true');
    }
  }

  function productsForPrint() {
    const list = state.filtered && state.filtered.length ? state.filtered : state.products;
    return [...list].sort((a, b) => {
      const categoryCompare = String(a.category || 'Sin categoría').localeCompare(String(b.category || 'Sin categoría'), 'es');
      if (categoryCompare !== 0) return categoryCompare;
      return compareProductsForCatalog(a, b);
    });
  }

  function groupProductsByCategory(products) {
    const groups = new Map();
    products.forEach((product) => {
      const category = String(product.category || 'Sin categoría').trim() || 'Sin categoría';
      if (!groups.has(category)) groups.set(category, []);
      groups.get(category).push(product);
    });
    return Array.from(groups.entries()).map(([category, items]) => ({ category, items }));
  }

  function printCategorySections(products, cardRenderer, gridClass) {
    const groups = groupProductsByCategory(products);
    if (!groups.length) return '<p>No hay productos para imprimir.</p>';
    return groups.map(({ category, items }) => `
      <section class="print-category-section">
        <div class="print-category-title">
          <h2>${escapeHtml(category)}</h2>
          <span>${items.length} ${items.length === 1 ? 'producto' : 'productos'}</span>
        </div>
        <div class="print-product-grid ${gridClass}">${items.map(cardRenderer).join('')}</div>
      </section>
    `).join('');
  }

  function preparePrintCatalog(type, options = {}) {
    const products = productsForPrint();
    document.body.dataset.printMode = type;
    if (!el.printCatalog) return;
    el.printCatalog.setAttribute('aria-hidden', 'false');
    el.printCatalog.innerHTML = type === 'comayagua'
      ? printComayaguaTemplate(products, Number(options.localShipping || 0))
      : printHondurasTemplate(products);
  }

  async function waitForPrintAssets() {
    if (!el.printCatalog) return;
    const images = Array.from(el.printCatalog.querySelectorAll('img'));
    await Promise.all(images.map((img) => new Promise((resolve) => {
      if (img.complete && img.naturalWidth) return resolve();
      const done = () => resolve();
      img.addEventListener('load', done, { once: true });
      img.addEventListener('error', done, { once: true });
    })));
    if (document.fonts && document.fonts.ready) {
      try { await document.fonts.ready; } catch { /* sin problema */ }
    }
    await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
  }

  function printHeaderTemplate(title, subtitle) {
    const now = formatDate(new Date().toISOString());
    return `
      <div class="print-catalog-head">
        <div class="print-brand">
          <img src="${PRINT_LOGO_SRC}" alt="Logo SD COMAYAGUA">
          <div>
            <strong>SD COMAYAGUA</strong>
            <span>${escapeHtml(title)}</span>
          </div>
        </div>
        <div class="print-date">
          <b>${escapeHtml(now)}</b>
          <span>${escapeHtml(subtitle)}</span>
        </div>
      </div>
    `;
  }

  function printCoverTemplate(type, localShipping = 0) {
    const now = formatDate(new Date().toISOString());
    const safeShipping = Math.max(0, Math.ceil(Number(localShipping || 0)));
    if (type === 'comayagua') {
      return `
        <section class="print-cover print-cover-comayagua">
          <div class="print-cover-inner">
            <img src="${PRINT_LOGO_SRC}" alt="Logo SD COMAYAGUA" class="print-cover-logo">
            <p class="print-cover-label">Catálogo local</p>
            <h1>SD COMAYAGUA</h1>
            <h2>Precios para Comayagua</h2>
            <div class="print-cover-box">
              <strong>¿Cómo se cobra el envío local?</strong>
              <p>El envío en Comayagua se cobra <b>una sola vez por pedido</b>, aunque el cliente compre varios productos.</p>
              <p>Ejemplo: si compra 3 productos, <b>no se cobra envío por cada producto</b>. El envío local sigue siendo ${formatMoneyWhole(safeShipping)} en total para ese pedido.</p>
              <p class="print-formula"><span>Fórmula:</span> productos comprados + envío local = total a pagar.</p>
            </div>
            <div class="print-cover-summary">
              <span>Envío local indicado</span>
              <strong>${formatMoneyWhole(safeShipping)}</strong>
            </div>
            <small>Fecha: ${escapeHtml(now)}</small>
          </div>
        </section>
      `;
    }

    return `
      <section class="print-cover print-cover-honduras">
        <div class="print-cover-inner">
          <img src="${PRINT_LOGO_SRC}" alt="Logo SD COMAYAGUA" class="print-cover-logo">
          <p class="print-cover-label">Catálogo nacional</p>
          <h1>SD COMAYAGUA</h1>
          <h2>Envíos a todo Honduras</h2>
          <div class="print-cover-box">
            <strong>¿Cómo calcular el total si quiere varios productos?</strong>
            <p>Primero se suma el precio de todos los productos que el cliente va a comprar. Esa es la <b>suma total de productos</b>.</p>
            <p>Ejemplo: producto 1 + producto 2 + producto 3 = suma total de productos.</p>
            <p><b>Envío normal:</b> suma total de productos + L 110.</p>
            <p><b>Pagar al recibir:</b> suma total de productos + L 110, y al resultado se le agrega el 10% de comisión.</p>
            <div class="print-methods">
              <p><b>Forma 1 para sacar el 10%:</b> resultado × 0.10 = comisión. Luego resultado + comisión = total a pagar.</p>
              <p><b>Forma 2 rápida:</b> resultado × 1.10 = total a pagar con comisión incluida.</p>
            </div>
            <p class="print-formula"><span>Fórmula pagar al recibir:</span> (productos + L 110) × 1.10</p>
          </div>
          <small>Fecha: ${escapeHtml(now)}</small>
        </div>
      </section>
    `;
  }

  function printComayaguaTemplate(products, localShipping) {
    const sections = printCategorySections(products, (product) => {
      const price = Number(product.price || 0);
      const total = roundToSafeLempira(price + localShipping);
      return `
        <article class="print-product-card print-local-card">
          ${printProductImage(product)}
          <div class="print-product-info">
            <span class="print-status ${getStockStatus(product.stock).key}">${getStockStatus(product.stock).label}</span>
            <h3>${escapeHtml(product.name)}</h3>
            <div class="print-price-line"><span>Producto</span><strong>${formatMoneyWhole(price)}</strong></div>
            <div class="print-price-line"><span>Envío Comayagua</span><strong>${formatMoneyWhole(localShipping)}</strong></div>
            <div class="print-price-line print-total"><span>Total</span><strong>${formatMoneyWhole(total)}</strong></div>
          </div>
        </article>
      `;
    }, 'local-print-grid');

    return `
      ${printCoverTemplate('comayagua', localShipping)}
      <div class="print-products-start">
        ${printHeaderTemplate('Productos por categoría', `Envío local: ${formatMoneyWhole(localShipping)}`)}
        <div class="print-note">Cada categoría inicia con su nombre. El envío local se cobra una sola vez por pedido, no por cada producto.</div>
        ${sections}
      </div>
    `;
  }

  function printHondurasTemplate(products) {
    const sections = printCategorySections(products, (product) => {
      const shipping = calculateShipping(product.price);
      return `
        <article class="print-product-card print-honduras-card">
          ${printProductImage(product)}
          <div class="print-product-info">
            <span class="print-status ${getStockStatus(product.stock).key}">${getStockStatus(product.stock).label}</span>
            <h3>${escapeHtml(product.name)}</h3>
            <div class="print-price-line"><span>Producto</span><strong>${formatMoneyWhole(product.price)}</strong></div>
            <div class="print-two-options">
              <div class="print-option normal"><span>Envío normal</span><em class="shipping-badge">MEJOR OPCIÓN</em><strong>${formatMoneyWhole(shipping.normal)}</strong><small>Depósito o transferencia antes de enviar. Ahorras: ${formatMoneySavings(getShippingSavings(shipping))}</small></div>
              <div class="print-option receive"><span>Pagar al recibir</span><strong>${formatMoneyWhole(shipping.receive)}</strong><small>Incluye envío + comisión del 10%.</small></div>
            </div>
          </div>
        </article>
      `;
    }, 'honduras-print-grid');

    return `
      ${printCoverTemplate('honduras')}
      <div class="print-products-start">
        ${printHeaderTemplate('Productos por categoría', 'Valores de referencia por producto')}
        <div class="print-note">Para varios productos, el cliente debe sumar los productos primero y luego aplicar el envío nacional según la explicación de la primera hoja.</div>
        ${sections}
      </div>
    `;
  }

  function printProductImage(product) {
    if (product.imageUrl) {
      return `<div class="print-product-image"><img src="${escapeAttr(product.imageUrl)}" alt="${escapeAttr(product.name)}"></div>`;
    }
    return `<div class="print-product-image print-placeholder">${placeholderMarkup(product.category)}</div>`;
  }

  function renderAll() {
    renderCategories();
    updateHideOutToggle();
    renderProducts();
    renderPanel();
    renderQuotesSection();
  }

  function renderCategories() {
    const previous = state.category;
    const categories = uniqueCategories(state.products);
    el.categoryFilter.innerHTML = '<option value="all">Todas</option>' + categories.map((category) => (
      `<option value="${escapeHtml(category)}">${escapeHtml(category)}</option>`
    )).join('');
    el.categoryFilter.value = categories.includes(previous) ? previous : 'all';
    state.category = el.categoryFilter.value;

    el.categorySuggestions.innerHTML = categories.map((category) => `<option value="${escapeHtml(category)}"></option>`).join('');

    if (el.quoteCategoryFilter) {
      const current = state.quoteCategory;
      el.quoteCategoryFilter.innerHTML = '<option value="">Elegir categoría</option><option value="all">Todas</option>' + categories.map((category) => (
        `<option value="${escapeHtml(category)}">${escapeHtml(category)}</option>`
      )).join('');
      el.quoteCategoryFilter.value = current === 'all' || categories.includes(current) ? current : '';
      state.quoteCategory = el.quoteCategoryFilter.value;
    }
  }

  function renderProducts() {
    const term = normalizeText(state.search);
    const duplicates = getDuplicateFlags();
    updateQuickFilterButtons();
    updateHideOutToggle();

    state.filtered = state.products.filter((product) => {
      const matchesCategory = state.category === 'all' || product.category === state.category;
      if (!matchesCategory) return false;

      if ((state.currentMode === 'cliente' || state.currentMode === 'envio') && state.hideOutInClient && Number(product.stock || 0) <= 0) return false;

      if (!matchesQuickFilter(product, state.quickFilter, duplicates)) return false;

      if (!term) return true;
      return matchesSmartSearch(product, term);
    });

    state.filtered.sort(compareProductsForCatalog);

    el.productGrid.innerHTML = state.filtered.map(productCardTemplate).join('');
    el.emptyProducts.hidden = state.filtered.length !== 0;
    renderStats();
    renderActiveFilters();
  }

